using UnityEngine;
public class JobOffer {public string scenarioId="";public float pickupSeconds;public int zoneIndex=-1;public int pickup,drop,fare,requiredScore;public float seconds,distance,waitSeconds;}
public class PassengerJobs : MonoBehaviour {
 public DriveSession session;public readonly FareTrip trip=new FareTrip(); public JobOffer[] offers=new JobOffer[3];public JobOffer current;
 public int balance,completed,failed;public string message="1·2·3으로 호출 선택 / 길가 손님 옆에 정차 후 F";
 public RoadNavigation nav;public MapStop[] stops;public GameObject[] people;public float[] cooldown;GameObject marker;float resultUntil;int generation;int offerPhase=-1;bool deadlineNotice,passengerChangeApplied;int passengerVia=-1;public int PassengerViaStop {get{return passengerVia;}}public bool PassengerViaPending {get{return passengerVia>=0;}}public string OfferId {get;private set;}
 public bool Active {get{return trip.State==TripState.ToPickup||trip.State==TripState.OnTrip;}}
 public void Initialize(DriveSession owner){session=owner;stops=session.world.map.stops;nav=gameObject.AddComponent<RoadNavigation>();nav.Build(session.world.map,session.taxi.transform);cooldown=new float[stops.Length];people=new GameObject[stops.Length];
  var coat=WorldBuilder.Mat("Passenger coat",new Color(.12f,.6f,.72f));var skin=WorldBuilder.Mat("Passenger head",new Color(.86f,.65f,.44f));
  for(int i=0;i<stops.Length;i++){var root=new GameObject(KoreanText.Stop(stops[i].name)+" passenger");root.transform.SetParent(transform);root.transform.position=stops[i].Passenger;people[i]=root;
   var arrow=new GameObject("승하차 진행 방향");arrow.transform.SetParent(transform);arrow.transform.position=stops[i].Kerb+Vector3.up*.14f;arrow.transform.rotation=Quaternion.LookRotation(stops[i].Direction);
   WorldBuilder.Box("정차 방향",Vector3.zero,new Vector3(.16f,.025f,3),coat,arrow.transform,false);
   foreach(int side in new[]{-1,1}){var tip=WorldBuilder.Box("화살표",new Vector3(side*.38f,0,1.1f),new Vector3(.15f,.025f,1.1f),coat,arrow.transform,false);tip.transform.localRotation=Quaternion.Euler(0,-side*45,0);}

   WorldBuilder.Box("Passenger body",new Vector3(0,.85f,0),new Vector3(.48f,1.15f,.3f),coat,root.transform,false);
   var head=GameObject.CreatePrimitive(PrimitiveType.Sphere);head.transform.SetParent(root.transform,false);head.transform.localPosition=Vector3.up*1.58f;head.transform.localScale=Vector3.one*.35f;head.GetComponent<Renderer>().sharedMaterial=skin;Destroy(head.GetComponent<Collider>());
   var label=new GameObject("Pickup label");label.transform.SetParent(root.transform,false);label.transform.localPosition=Vector3.up*2.3f;var text=label.AddComponent<TextMesh>();text.text=KoreanText.Stop(stops[i].name)+"\nF · 택시 탑승";text.fontSize=40;text.characterSize=.08f;text.anchor=TextAnchor.MiddleCenter;text.color=Color.cyan;KoreanText.Apply(text);label.AddComponent<FaceCamera>();
  }
  marker=GameObject.CreatePrimitive(PrimitiveType.Cylinder);marker.name="Pickup or destination zone";marker.transform.localScale=new Vector3(3,.03f,9);marker.GetComponent<Renderer>().sharedMaterial=WorldBuilder.Mat("Destination zone",new Color(.2f,.8f,.75f));Destroy(marker.GetComponent<Collider>());marker.SetActive(false);Generate();
 }
 JobOffer Make(int pickup,int drop,PrototypeScenario scenario=null){float distance=nav.Distance(stops[pickup],stops[drop]);var offer=new JobOffer{pickup=pickup,drop=drop,requiredScore=new[]{60,70,85}[(pickup+drop)%3],distance=distance};var zones=GetComponent<ServiceLawZones>();if(zones){if(scenario!=null){if(!zones.ConfigureScenario(offer,scenario))return null;}else zones.ConfigureOffer(offer);}offer.fare=3000+Mathf.CeilToInt(offer.distance*4/100)*100;offer.seconds=Mathf.Max(120,Mathf.Ceil(offer.distance/4+90+offer.waitSeconds));return offer;}
 public void ResetOffers(){generation=0;Generate();}
 public void Generate(){if(stops.Length<2)return;var zones=GetComponent<ServiceLawZones>();if(session.business!=null&&session.business.ledger!=null&&session.business.ledger.OneDay&&zones&&zones.Ready){var candidates=new System.Collections.Generic.List<JobOffer>();foreach(var course in zones.scenarios){var offer=Make(course.pickup,course.drop,course);if(offer!=null)candidates.Add(offer);}double elapsed=session.business.ledger.Elapsed;offerPhase=elapsed<300?0:elapsed<900?1:2;candidates.Sort((a,b)=>OfferRank(a,elapsed).CompareTo(OfferRank(b,elapsed)));for(int i=0;i<3;i++)offers[i]=i<candidates.Count?candidates[i]:null;generation++;return;}for(int i=0;i<3;i++){offers[i]=null;
  if(zones&&zones.Ready&&zones.scenarios.Count>0)for(int k=0;k<zones.scenarios.Count;k++){var scenario=zones.scenarios[(generation+i+k)%zones.scenarios.Count];bool duplicate=false;for(int j=0;j<i;j++)if(offers[j]!=null&&offers[j].scenarioId==scenario.id)duplicate=true;if(duplicate)continue;var candidate=Make(scenario.pickup,scenario.drop,scenario);if(candidate!=null){offers[i]=candidate;break;}}
  if(offers[i]==null){int p=(generation+i*2)%stops.Length,d=(p+3+i)%stops.Length;if(p==d)d=(d+1)%stops.Length;offers[i]=Make(p,d);}
 }generation++;} public bool Accept(int index){if(index<0||index>=offers.Length||offers[index]==null||trip.State!=TripState.Idle||Time.timeScale==0||!session.business.CanAccept)return false;current=offers[index];if(float.IsInfinity(current.distance))return false;float pickup=PickupBudget(current);if(float.IsInfinity(pickup)||!trip.Accept(current.fare,current.seconds,pickup))return false;OfferId=session.law?session.law.ids.Next("offer"):"offer";if(session.law)session.law.tripId=OfferId;message="호출 수락 · 픽업 장소: "+KoreanText.Stop(stops[current.pickup].name);SetGoal(current.pickup);var zones=GetComponent<ServiceLawZones>();if(zones)zones.BeginPickup(current);return true;}
 float OfferRank(JobOffer o,double elapsed){float pickup=Vector3.Distance(session.taxi.transform.position,stops[o.pickup].Kerb);float meal=Vector3.Distance(stops[o.drop].Kerb,stops[session.services.indices[1]].Kerb);int id=0;int.TryParse(o.scenarioId.Replace("PS",""),out id);return OneDayOfferPolicy.Rank(o.distance,pickup,meal,elapsed,id,generation);}
 void SetGoal(int index){nav.SetDestination(stops[index]);marker.transform.rotation=Quaternion.LookRotation(stops[index].Direction);marker.SetActive(true);marker.transform.position=stops[index].Kerb+Vector3.up*.085f;}
 public bool At(int index){return stops[index].CanStop(session.taxi.transform.position,session.taxi.transform.forward,session.taxi.body.velocity.magnitude);}
 float PickupBudget(JobOffer offer){
  if(offer.pickupSeconds>0&&string.IsNullOrEmpty(offer.scenarioId))return offer.pickupSeconds;
  if(nav.hd==null)return Mathf.Max(180,Vector3.Distance(session.taxi.transform.position,stops[offer.pickup].Kerb)/4+120);
  float at;int start=nav.hd.Nearest(session.taxi.transform.position,session.taxi.transform.forward,out at);var goal=stops[offer.pickup];if(start==goal.laneEdge&&Mathf.Abs(at-goal.laneAt)<.25f)return 180;var route=nav.hd.Route(start,at,goal.laneEdge,goal.laneAt);return route==null?float.PositiveInfinity:Mathf.Max(180,route.path.length/4+120);
 }
 public bool PreviewPassengerChange(int stop,bool via,out float extraDistance,out int newFare,out float newRemaining){
  extraDistance=0;newFare=trip.Fare;newRemaining=trip.Remaining;
  if(trip.State!=TripState.OnTrip||current==null||passengerChangeApplied||PassengerViaPending||trip.Remaining<=0||stop<0||stop>=stops.Length||stop==current.drop||nav.hd==null||session.taxi.body.velocity.magnitude>=.56f)return false;
  var zones=GetComponent<ServiceLawZones>();var course=GetComponent<ScenarioChoiceSituation>();if(zones&&zones.Live&&zones.Live.Active||course&&(course.Open||course.ActiveObservation))return false;
  float at;int start=nav.hd.Nearest(session.taxi.transform.position,session.taxi.transform.forward,out at);var goal=stops[current.drop];var target=stops[stop];
  var old=nav.hd.Route(start,at,goal.laneEdge,goal.laneAt);var changed=nav.hd.Route(start,at,target.laneEdge,target.laneAt);if(old==null||changed==null)return false;
  float distance=changed.path.length;if(via){var onward=nav.hd.Route(target.laneEdge,target.laneAt,goal.laneEdge,goal.laneAt);if(onward==null)return false;distance+=onward.path.length;}
  extraDistance=Mathf.Max(0,distance-old.path.length);newFare=trip.Fare+Mathf.CeilToInt(extraDistance*4/100)*100;newRemaining=trip.Remaining+extraDistance/4+30;return true;
 }
 public bool TryChangeDestination(int stop){return ApplyPassengerChange(stop,false);}
 public bool TrySetPassengerVia(int stop){return ApplyPassengerChange(stop,true);}
 bool ApplyPassengerChange(int stop,bool via){float extra,remaining;int fare;float priorRemaining=trip.Remaining;if(!PreviewPassengerChange(stop,via,out extra,out fare,out remaining)||!trip.Revise(fare,remaining))return false;passengerChangeApplied=true;if(via)passengerVia=stop;else current.drop=stop;current.fare=fare;current.seconds+=remaining-priorRemaining;current.distance+=extra;SetGoal(stop);message=via?"승객 경유 요청 수락 · 경유 장소에서 정차 후 F":"승객 목적지 변경 수락 · 새 목적지로 안내합니다";return true;}
System.Collections.Generic.Dictionary<JobOffer,float> fuelCache=new System.Collections.Generic.Dictionary<JobOffer,float>();float fuelCacheUntil;
 public float EstimatedFuel(JobOffer offer){if(offer==null)return float.PositiveInfinity;if(Time.unscaledTime>=fuelCacheUntil){fuelCache.Clear();fuelCacheUntil=Time.unscaledTime+1;}float cached;if(fuelCache.TryGetValue(offer,out cached))return cached;float pickup;
  if(nav.hd==null)pickup=Vector3.Distance(session.taxi.transform.position,stops[offer.pickup].Kerb);else {float at;int edge=nav.hd.Nearest(session.taxi.transform.position,session.taxi.transform.forward,out at);var goal=stops[offer.pickup];var route=nav.hd.Route(edge,at,goal.laneEdge,goal.laneAt);pickup=edge==goal.laneEdge&&Mathf.Abs(at-goal.laneAt)<.25f?0:route==null?float.PositiveInfinity:route.path.length;}
  var settings=session.business.settings;float need=(pickup+offer.distance)/1000*settings.fuelPerKm+(pickup/4+offer.seconds)/60*settings.idlePerMinute;fuelCache[offer]=need;return need;
 }
 public string FuelHint(JobOffer offer){float need=EstimatedFuel(offer);if(float.IsInfinity(need))return "연료 예측: 픽업 경로 확인 필요";float fuel=session.business.ledger.Account.Fuel;if(session.business.ledger.OneDay){var predicted=session.business.ledger.Driver.Copy();float seconds=(offer.distance+Vector3.Distance(session.taxi.transform.position,stops[offer.pickup].Kerb))/8+offer.waitSeconds;predicted.Advance(seconds);return "예상 연료 "+need.ToString("0.0")+"% · "+(fuel<need?"주유 권장 · ":"")+"운송 후 피로 약 "+predicted.fatigue.ToString("0")+" (교통에 따라 변동)"+(seconds>session.business.ledger.SecondsLeft?" · 마감 넘길 수 있음":"");}return "예상 연료 "+need.ToString("0.0")+"% · "+(fuel<need?"부족 예상 · 먼저 주유 권장":fuel<need+5?"도착 후 잔량 적음":"현재 잔량으로 운행 예상")+" (대기·우회에 따라 변동)";}
 public bool Interact(){if(Time.timeScale==0)return false;
  if(trip.State==TripState.Idle){if(!session.business.CanAccept)return false;int closest=-1;float best=8;for(int i=0;i<stops.Length;i++)if(Time.time>=cooldown[i]&&At(i)){float d=Vector3.Distance(session.taxi.transform.position,stops[i].Kerb);if(d<best){best=d;closest=i;}}
   if(closest<0){message="손님이 있는 오른쪽 연석에 같은 방향으로 정차하세요 (시속 2km 미만)";return false;}
   current=null;var roadsideZones=GetComponent<ServiceLawZones>();if(roadsideZones&&roadsideZones.Ready)foreach(var course in roadsideZones.scenarios)if(!course.beforePickup&&course.pickup==closest){current=Make(course.pickup,course.drop,course);if(current!=null)break;}if(current==null)current=Make(closest,(closest+3)%stops.Length);if(float.IsInfinity(current.distance))return false;trip.Accept(current.fare,current.seconds);OfferId="";return Board();
  }
  if(trip.State==TripState.ToPickup){if(!session.business.CanAccept)return false;if(!At(current.pickup)){message="승차 지점 오른쪽 연석에 화살표 방향으로 정차 후 F";return false;}return Board();}
  if(trip.State==TripState.OnTrip){if(PassengerViaPending){if(!At(passengerVia)){message="부탁한 경유 장소의 오른쪽 연석에 정차 후 F";return false;}passengerVia=-1;SetGoal(current.drop);message="경유 완료 · 최종 목적지로 출발하세요";return true;}if(!At(current.drop)){message="목적지 오른쪽 연석에 화살표 방향으로 정차 후 F";return false;}var zones=GetComponent<ServiceLawZones>();if(zones)zones.RecordSkippedDelivery();if(session.requests)session.requests.Finish();int pay=MannerLedger.Payment(trip.Complete(),session.manners.ledger.Score,current.requiredScore);
   if(trip.State==TripState.Failed){failed++;session.business.RecordPassenger(0,"시간 초과 후 목적지 도착");session.business.RecordFailure();message="늦은 도착 · 승객 하차 완료 / 요금 0원";Finish();return true;}
   if(pay<=0)return false;balance+=pay;completed++;session.business.RecordFare(pay);session.business.RecordPassenger(pay,"운송 완료");message=(session.manners.ledger.Score>=current.requiredScore?"요구 점수 달성! ":"요구 점수 미달 · 요금 70% 지급 ")+"+"+pay.ToString("N0")+"원";Finish();return true;}
  return false;
 }
 bool Board(){if(!trip.Board())return false;passengerChangeApplied=false;if(session.law){session.law.tripId=session.law.ids.Next("trip");if(!string.IsNullOrEmpty(OfferId)){var link=new LawEvent{id=session.law.ids.Next("boarding"),tripId=session.law.tripId,day=session.law.Day,family="호출 연결",scenario=current.scenarioId,occupied=true,reason="수락 호출 "+OfferId+" → 탑승 운송 "+session.law.tripId};link.Add("호출 연결",LawVerdict.NoOpportunity,0);session.law.ledger.Record(link);}}session.manners.BeginRide();cooldown[current.pickup]=Time.time+60;people[current.pickup].SetActive(false);message="승객 탑승 · 목적지: "+KoreanText.Stop(stops[current.drop].name);SetGoal(current.drop);var zones=GetComponent<ServiceLawZones>();if(zones)zones.BeginTrip(current);if(session.requests)session.requests.Begin();return true;}
 public void ClearForDay(){var zones=GetComponent<ServiceLawZones>();if(zones)zones.EndTrip();if(session.law)session.law.tripId="";trip.Clear();current=null;passengerVia=-1;passengerChangeApplied=false;OfferId="";resultUntil=0;deadlineNotice=false;nav.Clear();marker.SetActive(false);for(int i=0;i<cooldown.Length;i++)cooldown[i]=0;Generate();message="1·2·3으로 호출 선택 / 길가 손님 옆에 정차 후 F";}
 void Finish(){var zones=GetComponent<ServiceLawZones>();if(zones)zones.EndTrip();passengerVia=-1;nav.Clear();marker.SetActive(false);resultUntil=Time.time+4;}
 public void RecordExpiredTrip(){if(trip.State==TripState.OnTrip&&trip.Remaining<=0&&!deadlineNotice){deadlineNotice=true;message="제한 시간 초과 · 목적지까지 운송을 계속하세요 / 도착 후 요금 0원";}}
 void Update(){if(session.business.ledger.OneDay&&trip.State==TripState.Idle){double elapsed=session.business.ledger.Elapsed;int phase=elapsed<300?0:elapsed<900?1:2;if(phase!=offerPhase)Generate();}trip.Tick(Time.deltaTime);if(trip.PickupExpired&&resultUntil==0){message="승객 대기 시간 초과 · 호출 취소 / 요금 없음";Finish();if(session.law)session.law.tripId="";}RecordExpiredTrip();
  if(resultUntil>0&&Time.time>=resultUntil){trip.Clear();OfferId="";resultUntil=0;deadlineNotice=false;Generate();}
  var choice=GetComponent<ScenarioChoiceSituation>();if(Time.timeScale>0&&!(choice&&(choice.Open||choice.ClosedThisFrame))){if(Input.GetKeyDown(KeyCode.Alpha1))Accept(0);if(Input.GetKeyDown(KeyCode.Alpha2))Accept(1);if(Input.GetKeyDown(KeyCode.Alpha3))Accept(2);if(Input.GetKeyDown(KeyCode.F)||Input.GetKeyDown(KeyCode.JoystickButton8))Interact();}
  for(int i=0;i<people.Length;i++)people[i].SetActive((Time.time>=cooldown[i]||trip.State==TripState.ToPickup&&current.pickup==i)&&!(trip.State==TripState.OnTrip&&current.pickup==i));
 }
}
